head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _22 : dummy_chart (차트 삽입 옵션) 계열 중 격자선 / 범례 표시 옵션과 카테고리 영역 범위 옵션
//     - chart.catGridLines / chart.serGridLines / chart.legend / chart.legendPosition
//       / chart.catAxisRange / catAxisRange.startRowIndex / startColIndex / endRowIndex / endColIndex
//     같은 계열의 차트 본체 / 유형 / 제목 / 삽입 위치는 _21, serAxisRange + dataAxisRange 는 _23 에서 다룬다.
//     description 은 분리 샘플 공통(_1 과 동일).
//     ※ catGridLines / serGridLines / legend 는 가이드 타입이 Boolean 인데 false 를 전달해도
//        격자선과 범례가 그대로 표시된다. https://inswave01.atlassian.net/browse/WAEA-1217
//        결함 샘플 : jira/202609/fail_gridView_advancedExcelDownload_chartBooleanFalseIgnored.xml
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "chart.catGridLines(선택) 파라미터로 차트에 카테고리 격자선을 표시할지 true/false 로 설정합니다.",
        "chart.catGridLines(선택) 파라미터를 생략하면 기본값 true 가 적용됩니다.",
        "chart.serGridLines(선택) 파라미터로 차트에 시리즈 격자선을 표시할지 true/false 로 설정합니다.",
        "chart.serGridLines(선택) 파라미터를 생략하면 기본값 true 가 적용됩니다.",
        "chart.legend(선택) 파라미터로 차트에 범례를 표시할지 true/false 로 설정합니다.",
        "chart.legend(선택) 파라미터를 생략하면 기본값 true 가 적용됩니다.",
        "chart.legendPosition(선택) 파라미터로 차트에 표시할 범례의 위치를 'top'/'left'/'right'/'bottom' 으로 설정합니다.",
        "chart.legendPosition(선택) 파라미터를 생략하면 기본값 'bottom' 이 적용됩니다.",
        "chart.catAxisRange(선택) 파라미터로 차트에 적용될 카테고리 영역의 범위를 객체로 설정합니다.",
        "chart.catAxisRange(선택) 파라미터를 생략하면 기본값 {} 이 적용됩니다.",
        "chart.catAxisRange.startRowIndex(선택) 파라미터로 카테고리 영역의 시작 행 인덱스를 설정합니다.",
        "chart.catAxisRange.startRowIndex(선택) 파라미터를 생략하면 기본값 0 이 적용됩니다.",
        "chart.catAxisRange.startColIndex(선택) 파라미터로 카테고리 영역의 시작 열 인덱스를 설정합니다.",
        "chart.catAxisRange.startColIndex(선택) 파라미터를 생략하면 기본값 0 이 적용됩니다.",
        "chart.catAxisRange.endRowIndex(선택) 파라미터로 카테고리 영역의 마지막 행 인덱스를 설정합니다.",
        "chart.chartName 파라미터(차트 유형)값이 'area' 인 경우 chart.catAxisRange.endRowIndex 파라미터는 설정할 필요가 없습니다.",
        "chart.catAxisRange.endRowIndex(선택) 파라미터를 생략하면 기본값 0 이 적용됩니다.",
        "chart.catAxisRange.endColIndex(선택) 파라미터로 카테고리 영역의 마지막 열 인덱스를 설정합니다.",
        "chart.catAxisRange.endColIndex(선택) 파라미터를 생략하면 기본값 0 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 전제값을 명시한다.
    par_chartName.setValue("bar");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Header 1줄(병합 없음) / Body 6행 의 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · 차트가 참조할 수 있도록 Column 0 은 항목명(지역), Column 1~4 는 분기별 수치로 둔다.
//    Excel 파일에서 행 0 은 Header, 행 1~6 은 Body 6 행이 된다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Header 는 1줄(병합 없음), Body Column 인덱스 0 지역(text) / 1~4 분기별 수치(number), Body Row 는 6행\n- Excel 파일에서 행 0 은 Header, 행 1~6 은 Body 이며 열 0 은 지역, 열 1~4 는 Q1~Q4 다\n- chart.chartName 은 par 로 선택한다. catAxisRange.endRowIndex 하위절(차트 유형이 area 인 경우 설정할 필요가 없다)을 확인하기 위한 전제 토글이며 유형 자체는 _21 에서 다룬다. 기본값은 bar 다\n- chart.startRowIndex 9 / startColIndex 6 / endRowIndex 30 / endColIndex 12 를 고정 전달해 차트가 화면에 보이는 크기로 삽입되게 한다(본 계열 검증 대상 아님. _21 에서 다룸)\n- chart.serAxisRange 와 chart.dataAxisRange 는 차트가 그려지려면 필요하므로 고정 전달한다(본 계열 검증 대상 아님. _23 에서 다룸)\n- sheetName 은 mysheet, 파일명은 download_chart_cat, 확장자는 xlsx 로 고정 전달한다\n[절차]\n1. par 옵션(chart.catGridLines / chart.serGridLines / chart.legend / chart.legendPosition / chart.catAxisRange / catAxisRange.startRowIndex / startColIndex / endRowIndex / endColIndex) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n3. 내려받은 파일을 Excel 로 열어 차트를 확인한다\n[확인]\n- catGridLines / serGridLines / legend 세 개는 가이드 타입이 Boolean 이라 샘플이 Boolean 값으로 전달한다\n- chart.catGridLines : true 로 설정하거나 미설정이면 카테고리 격자선이 표시되는지. false 로 설정하면 표시되지 않아야 하지만, 현재는 false 로 설정해도 격자선이 그대로 표시된다\n- chart.serGridLines : true 로 설정하거나 미설정이면 시리즈 격자선이 표시되는지. false 로 설정하면 표시되지 않아야 하지만, 현재는 false 로 설정해도 격자선이 그대로 표시된다\n- chart.legend : true 로 설정하거나 미설정이면 범례가 표시되는지. false 로 설정하면 표시되지 않아야 하지만, 현재는 false 로 설정해도 범례가 그대로 표시된다\n- 위 세 항목은 같은 계열의 legendPosition 이 정상 동작하는 것과 대조된다. legendPosition 을 바꿔 범례 위치가 실제로 움직이는 것을 함께 확인하면 차트 옵션 전달 자체는 되고 있음을 알 수 있다\n- chart.legendPosition : 설정한 위치(top / left / right / bottom)에 범례가 표시되는지. 미설정이면 기본값 bottom 이 적용되어 차트 아래에 표시되는지\n- chart.catAxisRange : 미설정이면 카테고리 영역 범위가 지정되지 않아 차트의 항목 축이 어떻게 표시되는지. 설정하면 지정한 범위가 항목 축에 반영되는지\n- chart.catAxisRange 네 인덱스 : 설정한 행/열 인덱스가 항목 축 범위가 되는지. 시작 행 0 / 시작 열 1 / 마지막 행 0 / 마지막 열 4 로 두면 Header 행의 Q1~Q4 를 가리킨다(인덱스는 0 부터 시작)\n- 행 인덱스 두 개는 기본값이 0 이라 0 을 명시하면 생략했을 때와 결과가 같다. 반영 여부는 1 을 선택해 항목 축 범위가 한 행 아래로 내려가는지로 확인한다\n- 열 인덱스 두 개는 값이 두 가지씩이라 항목 축 범위가 실제로 좁아지고 넓어지는 것을 볼 수 있다. 시작 열 2 는 Q2 부터, 마지막 열 2 는 Q2 까지를 가리킨다\n- chart.catAxisRange 네 인덱스를 각각 생략하면 기본값 0 이 적용된다. 네 개를 모두 생략하면 범위가 행 0 / 열 0 한 칸으로 좁혀져 항목 축에 지역명 Header 한 칸만 잡히는지 확인한다\n- catAxisRange.endRowIndex 하위절 : chartName 을 area 로 두고 endRowIndex 를 생략해도 항목 축이 정상으로 표시되는지"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="q1" name="q1" dataType="number"></w2:column>';
    strDlt += '<w2:column id="q2" name="q2" dataType="number"></w2:column>';
    strDlt += '<w2:column id="q3" name="q3" dataType="number"></w2:column>';
    strDlt += '<w2:column id="q4" name="q4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "region" : "Seoul",   "q1" : 120, "q2" : 135, "q3" : 150, "q4" : 160 },
        { "region" : "Busan",   "q1" : 90,  "q2" : 100, "q3" : 95,  "q4" : 110 },
        { "region" : "Daegu",   "q1" : 70,  "q2" : 85,  "q3" : 80,  "q4" : 95 },
        { "region" : "Incheon", "q1" : 60,  "q2" : 65,  "q3" : 75,  "q4" : 70 },
        { "region" : "Gwangju", "q1" : 50,  "q2" : 55,  "q3" : 60,  "q4" : 58 },
        { "region" : "Daejeon", "q1" : 45,  "q2" : 48,  "q3" : 52,  "q4" : 50 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (차트 삽입 옵션 - 격자선 / 범례 / 카테고리 영역 범위) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol1" value="Region"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="Q1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="Q2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol4" value="Q3"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="Q4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<w2:column width="120" style="text-align:right;" inputType="text" dataType="number" id="q1" dataList="q1"></w2:column>';
    strTarget += '<w2:column width="120" style="text-align:right;" inputType="text" dataType="number" id="q2" dataList="q2"></w2:column>';
    strTarget += '<w2:column width="120" style="text-align:right;" inputType="text" dataType="number" id="q3" dataList="q3"></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="text" dataType="number" id="q4" dataList="q4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · catGridLines / serGridLines / legend 는 Boolean 타입이므로 selectbox 라벨을 Boolean 으로 변환해 전달한다.
//    (gdl_boolean 은 value 가 코드값 1 / 2 / 3 이라 getText 로 라벨을 읽는다.)
//  · catAxisRange 의 네 인덱스는 Number 타입이므로 정수로 변환해 전달한다.
//  · chartName / 삽입 위치 4 개 / serAxisRange / dataAxisRange 는 고정 전제값이며 본 계열의 검증 대상이 아니다.
scwin.buildOptions = function () {
    let options = { "fileName" : "download_chart_cat", "extension" : "xlsx", "sheetName" : "mysheet" };
    let arrDesc = [];

    let sChartName = par_chartName.getValue();
    let chart = {
        "chartName" : sChartName,
        "startRowIndex" : 9,
        "startColIndex" : 6,
        "endRowIndex" : 30,
        "endColIndex" : 12,
        "serAxisRange" : { "startRowIndex" : 1, "startColIndex" : 0, "endRowIndex" : 6, "endColIndex" : 4 },
        "dataAxisRange" : { "startRowIndex" : 1, "startColIndex" : 1, "endRowIndex" : 6, "endColIndex" : 4 }
    };

    let fnSet = function (sKey, vValue) {
        chart[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_catGridLines.getText();  if (v !== "") fnSet("catGridLines", (v === "true"));
    v = par_serGridLines.getText();  if (v !== "") fnSet("serGridLines", (v === "true"));
    v = par_legend.getText();        if (v !== "") fnSet("legend", (v === "true"));
    v = par_legendPosition.getValue(); if (v !== "") fnSet("legendPosition", v);

    if (par_catAxisRange.getValue() !== "") {
        let objRange = {};
        let arrRangeDesc = [];
        let fnRange = function (sKey, sValue) {
            if (sValue !== "") {
                objRange[sKey] = parseInt(sValue, 10);
                arrRangeDesc.push(sKey + "=" + sValue);
            }
        };
        fnRange("startRowIndex", par_catStartRowIndex.getValue());
        fnRange("startColIndex", par_catStartColIndex.getValue());
        fnRange("endRowIndex", par_catEndRowIndex.getValue());
        fnRange("endColIndex", par_catEndColIndex.getValue());

        chart.catAxisRange = objRange;
        arrDesc.push("catAxisRange 설정" + ((arrRangeDesc.length === 0) ? " (네 인덱스 전체 생략)" : (" {" + arrRangeDesc.join(", ") + "}")));
    }

    options.chart = chart;

    return { "options" : options, "desc" : "chartName=" + sChartName + ((arrDesc.length === 0) ? " / catGridLines / serGridLines / legend / legendPosition / catAxisRange 전체 생략" : (" / " + arrDesc.join(" / "))) };
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    target1.advancedExcelDownload(objBuild.options);

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
}
